// (1) SERVICE: @Injectable shared logic. providedIn:'root' = one instance app-wide.
@Injectable({ providedIn: 'root' })
export class CartService {
  private items: string[] = [];
  add(item: string) { this.items.push(item); }
  get count() { return this.items.length; }
}

// (2) COMPONENT asks for the service in its constructor; Angular INJECTS it.
@Component({ selector: 'app-cart', template: `<button (click)="add()">Add ({{count}})</button>` })
export class CartComponent {
  constructor(private cart: CartService) {}   // ANGULAR injects it
  count = 0; add() { this.cart.add('item'); this.count = this.cart.count; }
}
//   Because CartService is providedIn:'root', every component gets the SAME
//   instance -> shared cart state. In a test, you pass a mock instead.
```
